import {interfacePair,neatPhotos} from './visuals.mjs';
export function renderNarratives(h) {
  const {photo,video,doc,link,opening,head}=h;
  const inlineLinks=[
    ['AmbuGo','https://github.com/mj-112358/AmbuGo-Final'],
    ['EcoFog','documents/ecofog-paper.pdf'],
    ['complex singularity atoms','documents/math-paper.pdf'],
    ['reduced-order law','documents/physics-paper.pdf'],
    ['Kids Cancer Foundation','https://kidscancerfoundation.org/'],
    ['PredictX','https://predictxportal.com/'],
    ['Musica Universalis','https://musicauni.netlify.app/'],
    ['Students For Last-Mile Learning','https://www.sflml.com/'],
    ['Soul of Symphony','https://www.soulofsymphony.in/'],
    ['Professor Femida Handy’s academic website','https://femidahandy.com/'],
    ['Niraksha','https://projectniraksha.vercel.app/'],
    ['Eclipse SUMO','https://eclipse.dev/sumo/'],
    ['IEEE ICESC 2025','https://ieeexplore.ieee.org/document/11212452'],
    ['later spirometry work','spirometry.html']
  ];
  const p=text=>{
    let copy=text.trim().replace(/  +/g,' ');
    for(const [label,url] of inlineLinks) copy=copy.replace(label,`<a class="inline-link" href="${url}" target="_blank" rel="noopener">${label}</a>`);

    return copy?`<p>${copy}</p>`:'';
  };
  const beat=(copy,visual='',heading='')=>`<section class="story-beat ${visual?'with-visual':'text-only'}">${visual?`<div class="story-visual">${visual}</div>`:''}<div class="story-copy">${heading?`<h3>${heading}</h3>`:''}${copy}</div></section>`;
  const sources=(items,id)=>`<details class="story-sources"><summary>${({ambugo:"Paper, code & deployment",ecofog:"Paper, presentation & awards",predictx:"Portal, code & hospital records",aeris:"Publication & hardware",niraksha:"Project website",timbre:"Paper & finalist record",capstan:"Paper & finalist record",spirometry:"Paper & evaluation","ambugo-study":"Paper & experiments","human-archive":"Internship letter & demonstrations",wink:"Project demonstration & résumé",handy:"Website & résumé",guitar:"Music activities",musica:"Programme & partners",learning:"Initiative & endorsement letters",school:"Leadership & mentoring",care:"Foundation & activity record"})[id]||"Supporting documents"}</summary><div class="source-links">${items.join('')}${link('proofs.html','All letters & documents')}</div></details>`;
  const cover=id=>id==='ecofog'?`<div class="source-photo-pair">${photo('ecofog-prototypes-slide','Support geometries tested during development, extracted from my ISEF presentation.')}${photo('ecofog-pla-slide','The printed PLA support used for the capture matrix, from my ISEF presentation.')}</div>`:'';
  const projectSubheads={
    ambugo:['Routing and signals','When to intervene','Simulation results','Field deployment'],
    ecofog:['Capture and drainage','Fabrication and material tests','Choosing a formulation','Outdoor collection'],
    predictx:['One report, five assessments','Reusing compatible calculations','Hospital evaluation'],
    aeris:['From speech to a wristband','Recognition models and field trials'],
    niraksha:['Detection to response','Farm testing'],
    timbre:['A compact model of harmonics','Reconstruction and prediction','What the parameters reveal'],
    capstan:['Predicting the slip boundary','The physical experiment','Identifying a measurable boundary','Prediction against measurement'],
    spirometry:['The missing end of a breath','Selecting reliable decisions','Independent evaluation'],
    'ambugo-study':['Matched traffic experiments','Measuring the trade-off'],
    'human-archive':['Hand-movement representations','Data quality and robot trials','Factory partnerships'],
    wink:['Tracking store visits','From movement to a dashboard','Running analysis in the store']
  };
  const structure=(id,body)=>{
    let index=0;
    return body.replace(/<div class="story-copy">/g,tag=>{
      const label=projectSubheads[id]?.[index++];
      return label?`${tag}<h3>${label}</h3>`:tag;
    });
  };
  const story=(id,title,subtitle,body,records=[])=>`<article class="case-study wrap" id="${id}">${id==='musica'?`<header class="musica-hero"><div class="musica-title"><h2><span>Musica</span><span>Universalis</span></h2><p class="role-meta">${subtitle}</p></div>${photo('musica-extra-0','Introducing a musical idea in a classroom session.')}</header>`:head(title,subtitle)}${cover(id)}${structure(id,body)}${records.length?sources(records,id):''}</article>`;
  const flow=(caption,steps)=>`<figure class="method-flow"><ol>${steps.map(([title,detail])=>`<li><strong>${title}</strong><span>${detail}</span></li>`).join('')}</ol><figcaption>${caption}</figcaption></figure>`;

  const projects=opening('Projects',[['ambugo','AmbuGo'],['ecofog','EcoFog'],['predictx','PredictX'],['aeris','AERIS'],['niraksha','Niraksha']])+
  story('ambugo','AmbuGo','Ambulance routing and traffic-signal control',
    beat(p("A green light can clear an ambulance through one junction while moving a queue onto the road ahead. I built AmbuGo to choose the route and the traffic-signal changes together, estimating how each proposed intervention would affect the rest of the journey.")+p("I designed the integration to reuse existing number-plate-recognition cameras, known as ANPR, and authorized connections to installed signal controllers. Available vehicle detections feed estimates of traffic conditions; the software then decides which route and signal requests to use, without adding a dedicated roadside sensor network."))+
    interfacePair()+
    `<div class="case-film">${video('ambugo','Simulation of route selection and signal priority. Watch how an intervention changes both the ambulance’s passage and the queues on competing approaches.')}</div>`+
    beat(p("The controller uses a finite route–action search to compare possible routes and signal requests. The objective is minimum intervention: preserve a computed arrival-time allowance while reducing predicted traffic burden. It first finds route and signal choices that meet the predicted arrival-time target, then chooses the one expected to disrupt other traffic least. Before changing a light, it checks that the junction can complete the required green and clearance intervals and that the next road has room for the released vehicles. This connects a route that looks attractive in the model to a signal change the junction can actually carry out.")+p("AmbuGo also checks whether the ambulance is making the expected progress along its route. This progress-based escalation rule adds feedback to the selective-priority policy. If delay builds up, the software switches from limited intervention to stronger priority. I tested this safeguard by repeating the simulations with it disabled: at the highest studied traffic load, ambulance journeys took 38.82 seconds longer on average. That comparison tests whether responding to the ambulance’s actual movement improves the journey."),flow('Schematic of the implemented controller’s decision cycle.',[['Observe current traffic','Use ambulance telemetry and available traffic counts.'],['Compare route–priority choices','Score travel time and traffic burden together.'],['Request a feasible intervention','Check signal phases and downstream receiving space.'],['Measure progress & repeat','Escalate priority when observed movement falls behind.']]))+
    beat(p("I evaluated the system in two traffic models: 14,400 policy runs in a coarser, queue-based mesoscopic model and 1,728 held-out microscopic policy runs in Eclipse SUMO, which simulates individual vehicles, their following behaviour, lane changes, and junction movements. Competing approaches faced matching traffic demand and observation errors. I also counted vehicles waiting to enter the network and trips still in progress, then checked the totals against individual vehicle records so each comparison followed the same traffic population. Paired seed-block bootstraps over 48 matched evaluation seeds quantified uncertainty while retaining the dependence between missions in each run.")+p("Selective priority retained about 94% of aggressive priority’s ambulance-time saving while causing less disruption to ordinary traffic. Mean ambulance duration fell from 401.57 seconds with routing alone to 222.29 seconds with selective control. Compared with aggressive control, selective priority added 11.10 seconds while reducing accumulated excess road occupancy by 3.84 vehicle-hours. That measure adds up local increases in moving and stopped vehicles over time relative to routing alone. The result is a substantial emergency-time benefit with a smaller traffic burden than aggressive priority."),photo('ambugo-paired-results','Selective priority (JSEL) versus aggressive priority (JFAST). The upper plot compares journey time; the lower compares accumulated road-occupancy increases. Bars show 95% uncertainty intervals.'))+
    beat(p("The field programme was evaluated separately from those simulations. A 31-intersection Punjab pilot recorded approximately 32% lower emergency response time. Phase 1 began in August 2026 across 121 intersections, supporting roughly 700 ambulance movements daily.")),
    [doc('ambugo-paper','Research paper'),link('https://github.com/mj-112358/AmbuGo-Final','Code & experiments'),doc('ambugo-deployment','Deployment agreement')])+
  story('ecofog','EcoFog','A fog-collecting mesh that combines capture and drainage',
    beat(p("Fog collectors catch tiny airborne droplets, but water that remains stuck between the fibres can obstruct further collection. I designed EcoFog around two complementary surfaces: water-attracting fibres catch and merge droplets, while a water-repelling, 3D-printed frame supports the network and helps the collected water leave it. This coplanar capture–drainage architecture places both functions in the same flat layer, combining hydrophilic and hydrophobic regions.")+p("The fibres combine polyvinyl alcohol (PVA), which attracts water, with polyethylene oxide (PEO), which helps stabilize the spinning process. Titanium-dioxide particles provide additional sites for droplets to form; silica particles reinforce the fibre network. My work included the frame openings, polymer blend, and particle concentrations, connecting each material choice to a role in capture, drainage, or strength."),photo('ecofog-frame','PLA support geometry. The open frame provides the larger drainage structure around the electrospun capture matrix.'))+
    beat(p("I made the fine fibres by electrospinning: an electric field draws a polymer solution into thin strands deposited across the frame. I then treated the network with glutaraldehyde, which forms chemical bridges between PVA chains called acetal crosslinks. These bridges help the fibres remain intact in water. I varied spinning distance, polymer concentration, blend ratio, and particle loading to examine how these choices changed the resulting material.")+p("Electron microscopy (FESEM) showed whether the fibres were continuous and how the particles were distributed. Infrared spectroscopy (FTIR) tested the chemical changes associated with crosslinking. Sessile-drop contact-angle measurements tested the intended surface contrast: droplets spread on the capture matrix, with angles of 20.9–23.9°, and bead more strongly on PLA, at approximately 100°. The selected formulation used an 18 wt% polymer solution, a 90:10 PVA:PEO ratio, and 1 wt% of each oxide filler."),neatPhotos([['ecofog-fabrication','Electrospinning the capture fibres.'],['ecofog-chamber-slide','Fog-chamber setup used to compare collection under controlled conditions.']],photo,'ecofog-test-pair'))+
    beat(p("The titanium-dioxide sweep showed why particle concentration needed to be tested rather than simply increased. Collection improved up to the tested 1 wt% setting, then declined at higher loadings. Microscopy connected those higher loadings with less uniform fibres and particle clusters, linking the measured collection rate to a visible change in the material.")+p("I also explored Gaussian-process regression on 36 preliminary fog-chamber measurements. This statistical model estimates collection performance together with uncertainty, offering a way to choose which material setting would be most informative to test next. The formulation reported here was selected through the measured material and collection experiments."),photo('ecofog-particle-result','Collection rate versus TiO₂ loading. This experiment informed the formulation choice, rather than treating higher filler concentration as automatically better.'))+
    beat(p("I compared the complete composite with a bare PLA frame and conventional Raschel mesh. Testing the bare frame separately helps identify what the added fibres contribute. In simultaneous five-day outdoor testing, EcoFog collected 17.3 ± 2.1 litres per square metre per day, compared with 4.6 ± 0.51 for Raschel mesh.")+p("Higher collection was accompanied by a roughly 50% lower retained-water fraction: a larger share of the water caught by the mesh drained into the collector instead of remaining on the fibres. Measuring both quantities tests the capture–drainage design directly, rather than treating intercepted droplets as recovered water. Collection itself requires no grid power. The research received the Regeneron ISEF Third Grand Award."),photo('ecofog-results','Outdoor collection and retained-water comparison. The separate PLA-support condition helps isolate the role of the capture matrix.')),
    [doc('ecofog-presentation','ISEF presentation'),doc('ecofog-paper','Full research paper'),doc('ecofog-poster','ISEF poster'),doc('isef-award','ISEF award certificate'),doc('sjwp-award','National Water Champion certificate'),doc('earth-prize','Earth Prize Asia Runner-Up letter')])+
  story('predictx','PredictX','Coordinated disease screening from routine laboratory reports',
    `<div class="report-flow">${flow('How a laboratory report becomes five separate assessments.',[['Read the report','Collect the available blood and urine measurements.'],['Check the inputs','Check units, definitions, and model compatibility.'],['Run the models','Keep each disease model’s fitted processing and calibration.'],['Return assessments','Report the separate risk estimates.']])}</div>`+
    beat(p("PredictX takes an existing blood-and-urine laboratory report and produces five separate disease-risk assessments. I developed the system to coordinate independently trained models whose required measurements, numerical processing, and calibration differ. The engineering task was to make one report usable across those models while preserving the inputs each model was trained to interpret.")+p("I built a shared laboratory-data processor that checks observations, converts units, and calculates biochemical ratios. I implemented compatibility-controlled preprocessing: the system reuses a calculation only when the models’ feature definitions and saved processing settings match. Its compatibility signature includes ordered features, fitted imputation values for missing measurements, scaling parameters, and missing-value indicators. A versioned registry stores those settings with each model, and a SHA-256 fingerprint checks that the loaded model file is the expected one. The FastAPI service processes up to 128 records per batch and returns separate assessments in a downloadable JSON report."),`<div class="portal-inline">${photo('predictx-portal','The portal brings the five assessments into one report workflow.')}</div>`)+
    beat(p("Compatibility-controlled reuse reduced repeated laboratory conversions by 80% in the reported five-model workflow. It removes duplicate work across assessments while preserving each model’s fitted inputs and calibration. The biochemical definitions matter: HOMA-IR depends on fasting glucose and insulin, while eGFR estimates kidney filtration using specified age and creatinine inputs. Reusing a calculation only when these definitions and processing settings match lets the system coordinate models without making their inputs interchangeable.")+p("I tested each model on records not used to train it. AUROC measures how well a model gives higher risk scores to people with a disease than to people without it. A value of 0.5 means random ranking, while 1.0 means perfect separation in the tested records. The diabetes model achieved 0.923 on 1,011 test records: when randomly pairing one person with diabetes and one without, it assigns the higher score to the person with diabetes about 92.3% of the time. Cardiovascular screening achieved 0.785 on 1,039 records. Each row represents a separate disease cohort.")+`<details class="model-results"><summary>Held-out results for all five models</summary><div class="table-scroll"><table><thead><tr><th>Model</th><th>Test records</th><th>AUROC</th></tr></thead><tbody><tr><td>Diabetes</td><td>1,011</td><td>0.923</td></tr><tr><td>Kidney</td><td>80</td><td>1.000</td></tr><tr><td>Liver</td><td>114</td><td>0.760</td></tr><tr><td>Cardiovascular</td><td>1,039</td><td>0.785</td></tr><tr><td>Breast cancer</td><td>24</td><td>0.922</td></tr></tbody></table></div><p>Each row reports a separate test cohort. Higher AUROC values indicate better separation between people with and without the disease. Test records were not used to train the model.</p></details>`,photo('predictx-assessment','The diabetes assessment retains its own required measurements and model-applicability inputs.'))+
    beat(p("Under Dr. Naresh Somani’s mentorship, I led a hospital-based evaluation involving more than 3,000 people at five hospitals. Follow-up standard tests corroborated suspected conditions in approximately 65% of high-risk cases, connecting the report-to-risk workflow to clinically checked findings. That percentage describes confirmation among flagged cases; the model-discrimination results above come from the separate held-out datasets.")+p("I secured a ₹20 lakh CSR sanction for further research and development. I then extended PredictX to another measurement problem: deciding whether a breathing test that ends too early can still provide useful information about airway obstruction. That work combines a model of exhalation with a separate method for selecting reliable screening decisions."))+`<div class="clinical-photos">${photo('predictx-0','Testing the report workflow in a hospital setting.')}${photo('predictx-1','Discussing the screening workflow with hospital staff.')}${photo('predictx-2','Clinical evaluation and follow-up.')}</div>`,
    [link('https://predictxportal.com/','PredictX portal'),doc('predictx-patent','Provisional-patent manuscript'),link('https://github.com/mj-112358/PredictX-Final','Code repository'),doc('predictx-funding','CSR funding sanction'),link('proofs.html#clinical-records','Five-site MoUs & evaluation reports'),link('spirometry.html','Physics-informed spirometry research')])+
  story('aeris','AERIS','Speech and emotion recognition connected to haptic feedback',
    beat(p("A transcript records words, while a conversation also carries clues about who is speaking and how their voice sounds. I developed AERIS to identify a speaker and classify vocal emotion, then display those labels and deliver five distinct vibration patterns through a wrist-worn device.")+p("The audio analysis runs on a Raspberry Pi 4 computer. It sends the speaker and emotion labels over Wi-Fi to an ESP32 controller in the wrist unit, which operates an OLED display and vibration motor. This separates the heavier recognition work from the smaller wearable interface."),photo('aeris-device-new','The wrist unit displays speaker and emotion labels and delivers the matching vibration pattern.'))+
    beat(p("For speaker recognition, I converted each audio sample into 40 Mel-frequency cepstral coefficients (MFCCs), a compact summary of the speech spectrum. A three-layer convolutional neural network learns patterns in those feature values; each layer uses 64 filters, a kernel width of 3, and max-pooling, and a 512-unit dense layer feeds probabilities for four known speaker profiles. I checked validation performance during training and used early stopping when improvement stalled. A separate pretrained Wav2Vec2 model classifies neutral, happy, sad, angry, and fearful speech.")+p("The published four-class speaker task achieved 99.3% classification accuracy, and the software evaluation reported an average response time of roughly 250 milliseconds, or one quarter of a second. Together, these measurements test whether the software identifies a known speaker correctly and returns an answer quickly enough to update conversational feedback. I published that software architecture as first-author research at IEEE ICESC 2025, then developed the documented wearable extension. Demonstrations with children and families tested how the visible labels and vibration patterns communicated the software’s outputs."),photo('aeris-field-0','Demonstrating AERIS to children and families.')),
    [link('https://ieeexplore.ieee.org/document/11212452','IEEE publication'),doc('aeris-ieee-paper','Paper PDF'),doc('aeris-prototype','Hardware documentation')])+
  story('niraksha','Project Niraksha','Image detection and drone-response integration',
    beat(p("Niraksha uses a drone to detect crop pests and guide a targeted response. I developed the image-detection pipeline and connected its predictions to the drone’s response system, so a camera observation could be carried through to a physical action at the platform.")+p("The wider project combines three kinds of image analysis: YOLOv8-s finds objects, DeepLabv3+ performs semantic segmentation, labelling image regions, and DINOv2 supplies features for detecting unusual patterns. Light, temperature, humidity, and pressure measurements inform its adaptive-fusion rule, which adjusts the weight given to those outputs. A Raspberry Pi 5 runs the image analysis alongside the flight controller, which handles stabilization and navigation. My integration connects the resulting detection to the response logic."),photo('drone-build','Drone assembly during development and integration testing.'))+
    beat(p("I tested the assembled detection-to-response sequence in a farm setting, including operation by a village representative. Changing light and crop scenes exercised the software and physical platform together. The intended benefit is location-specific treatment driven by detection; these trials checked the complete chain from a camera observation to an operator-controlled response in the farm setting."),video('drone-farm','Farm demonstration with a village representative operating the drone.')),
    [link('https://projectniraksha.vercel.app/','Project website'),link('videos/drone-field.mp4','Additional field-use footage')]);

  const research=opening('Research',[['timbre','Timbre modelling'],['capstan','Capstan friction'],['spirometry','Spirometry'],['ambugo-study','Traffic control']])+
  story('timbre','Music timbre modelling','Reconstructing sound from a compact model of its harmonics',
    beat(p("A flute and a guitar can play the same note yet sound different because their overtones have different strengths and change differently over time. I modelled that evolving structure through time-varying complex harmonic coefficients, preserving each overtone’s strength and phase, which describes how its wave lines up with the others.")+p("The model uses components called complex singularity atoms to describe many harmonics with a small set of parameters. Their depth controls how quickly higher harmonics fade, their angular position changes phase, and their type shapes the envelope. I helped derive when measured harmonics determine a unique set of parameters, apart from reordering equivalent components. I separated estimating each component’s strength from fitting its shape. In variable projection, strengths are calculated by linear least squares for each candidate shape, keeping them out of the harder nonlinear search. For K components, this reduces that search from 5K to 3K parameters while still fitting the full harmonic pattern. A matrix-pencil initializer provides starting estimates for integer-type singularity atoms before nonlinear refinement."),photo('math-dynamics','Synthetic test from Figure 3: tracking the evolving signature through an attack transient and reconstructing the waveform.'))+
    beat(p("Letting those parameters change over time extends the representation to a note’s attack and decay. I tested the recovered trajectories on synthetic signals and tested harmonic reconstruction on 72 isolated tones from the University of Iowa instrument recordings. The waveform and spectrum comparisons show whether the compact representation preserves the measured harmonic sound.")+p("Across 72 isolated instrument tones, the representation retained 93.6% of harmonic coefficient energy, with a median normalized complex reconstruction error of 0.253; zero would mean exact reconstruction. The parameter-budget study compares 170 model values with 1,088 direct coefficient-knot values, testing how much harmonic structure a compact representation preserves. In synthetic tests, fitting the first 24 harmonics predicted the next 24 with 1.5% median relative error. Reconstruction tests the measured sound; predicting unseen harmonics tests whether the fitted signature captures structure beyond the measurements used to estimate it."),photo('math-reconstruction','Waveform and spectral reconstruction for two Iowa tones, extracted from Figure 5 of the paper.'))+beat(p("The mathematical analysis also connects the model to interpretable sound properties. Energy and spectral centroid, the average frequency weighted by harmonic energy, can be calculated from the parameters, including interactions between components. I also examined how the measured harmonics respond to changes in each parameter, using the coefficient-map Jacobian. This tests when nearby parameter changes remain distinguishable in the measurements, so the model can recover them. Synthetic trajectory and conditioning tests connect these theoretical conditions to the numerical fitting method."),photo('math-conditioning','Figure 2: coefficient reconstruction, held-out harmonic prediction, and parameter recovery across controlled signature separations.')),
    [doc('math-paper','Mathematics paper'),doc('yau-math','S.-T. Yau Mathematics finalist letter')])+
  story('capstan','Vibration-driven rope slip','Predicting where a wrapped rope changes from creeping to gripping',
    beat(p("A rope wrapped around a vibrating drum can slip near one end while holding firmly farther around the contact. I derived an equation predicting where that change from creeping to gripping occurs. The question is spatial: which part of the wrapped rope moves, and where does the movement stop?")+p("The equation compares the vibration-driven force with the friction resisting movement along the wrap. Their crossover predicts the boundary. It combines the capstan relation, which describes how tension changes around a wrapped contact, with measured preslip stiffness: how restoring force builds during small relative movements before larger sliding occurs. Balancing those terms yields a closed-form, logarithmic amplitude–tension law for the transition position."),photo('capstan-forces','Force-crossover schematic extracted from the presentation. The predicted transition is the intersection of loading and effective resistance.'))+
    beat(p("I tested a four-wrap braided polyester rope on a torsionally oscillated aluminium capstan. The experiment comprised 84 physical runs across 14 conditions, with six repeats per condition. I varied vibration amplitude and holding tension separately so that their effects on the boundary could be compared with the equation’s predictions.")+p("I measured geometry, drive amplitude, friction, contact stiffness, and the camera’s measurement floor before testing boundary positions. This keeps the prediction independent of the positions used to assess it. Camera tracking and regression then measured how quickly different rope locations moved relative to the drum."),photo('physics-apparatus','Experimental apparatus used for the vibration sweeps and independent mechanical calibration.'))+
    beat(p("The recorded motion could form several spatial patterns, so I compared five candidate descriptions using Bayesian Information Criterion. This criterion balances how closely a model fits the observations against how many parameters it uses. It helps test whether a localized boundary explains the data better than a simpler drift or another motion pattern.")+p("I reported a boundary only when it met additional measurement checks: a BIC advantage of at least 10 over patterns without a localized boundary, a motion signal above three times the independently measured noise floor, and a location separated from the observation boundaries. These checks connect a reported slip front to a distinguishable feature of the measured motion."),photo('capstan-creep-profile','Creep-rate profile schematic from the presentation, illustrating how the transition position is extracted.'))+
    beat(p("Across eight unique amplitude–tension settings, the calibration-fixed equation predicted the boundary with a root-mean-square angular error of 0.117 rad, equivalent to 6.7°. The mechanical constants were measured independently, so this agreement tests a prediction of the force-balance model rather than a curve fitted to the boundary positions.")+p("The amplitude and tension sweeps tested the mechanism in two independently varied directions. Measured sensitivity to log amplitude was 9.54 ± 0.74 rad, compared with 10.10 ± 1.45 predicted; sensitivity to log holding tension was −5.56 ± 0.50 rad, compared with −5.56 ± 0.62 predicted. These slopes describe how the boundary responds to proportional input changes. Agreement in both sign and magnitude connects the observed motion to the competing vibration and friction terms in the equation."),photo('capstan-validation','Each marker compares a predicted boundary angle with its measured value. Points near the diagonal indicate agreement.')),
    [doc('physics-paper','Full physics report'),doc('capstan-presentation','Presentation (PDF)'),doc('yau-physics','S.-T. Yau Physics finalist letter')])+
  story('spirometry','Physics-informed spirometry','Selective inference from incomplete expiratory recordings',
    beat(p("Spirometry measures how much air a person exhales and how quickly. Airway-obstruction screening often compares the volume exhaled in the first second (FEV₁) with the total exhaled volume (FVC). If the person stops too early, the recorded total can be too small, raising the ratio and hiding obstruction that a completed test would reveal.")+p("I decoded NHANES health-survey recordings at 100 samples per second and aligned the beginning of each exhalation by back-extrapolated onset. For an incomplete recording, I fitted a bounded two-compartment volume model with fast and slow emptying components to the measured portion of the curve. The model estimates how exhalation would continue toward its final volume; complete recordings provide a reference for testing that estimate."),photo('spirometry-curves','Orange is the measured start of an exhalation, blue is the model’s estimated continuation, and grey is the completed reference recording.'))+
    beat(p("I then developed a physics-informed reliability selector: a second model predicting which screening decisions were likely to be reliable. It uses how well the exhalation curve fits, the remaining change in volume, recording length, and agreement between the physiological estimate and a statistical ridge-regression estimate. The two methods contribute different information about the missing endpoint.")+p("At 75% coverage, the system classifies the three-quarters of the tests it judges most reliable and withholds a classification for the rest. I trained this selection step with participant-separated cross-fitting, so a person’s records were not used both to fit a model and judge its predictions. Final evaluation used separate NHANES survey cycles, testing the frozen method on a new participant group."))+
    beat(p("Reconstructing the missing end of exhalation revealed obstruction that early stopping had hidden: missed obstruction fell from 42.7% to 6.7% in naturally incomplete recordings. At 75% coverage in independent NHANES Cycles E and G, sensitivity was 96.0% and 96.1%, meaning those proportions of obstructed recordings were identified. Specificity was 99.7% and 99.8%, measuring correct classification of non-obstructed recordings. Agreement beyond chance, measured by Cohen’s kappa, was 0.952 and 0.959; 1 represents perfect agreement.")+p("I compared selectors allowed to classify the same proportion of tests, so the comparison tests the information used to choose cases rather than a difference in how many answers are accepted. Kappa exceeded a capacity-matched ridge-feature selector by 0.019 and 0.030 on Cycles E and G, with paired bootstrap intervals excluding zero. The physiological features improved which recordings were selected for a screening decision at the same coverage.")),
    [link('spirometry.html','Standalone research page'),doc('spirometry-paper','Full spirometry study'),doc('predictx-patent','PredictX architecture')])+
  story('ambugo-study','AmbuGo simulation study','Paired evaluation of joint routing and selective priority',
    beat(p("I tested whether AmbuGo could keep most of the ambulance-time benefit of aggressive priority while causing less disruption to surrounding traffic. The comparisons used the same computer-generated road network and traffic-demand schedules. Vehicles followed and changed lanes individually; road capacity, signal transitions, and imperfect traffic observations were represented in the model.")+p("The competing controllers received matching traffic-demand and observation-error draws. The evaluation seeds were held out from development, and differences were measured within matched runs. This helps distinguish an effect of the controller from an easier traffic scenario."),photo('ambugo-topology','The computer-generated road network used to compare the controllers under matching traffic conditions, including the hospital destination.'))+
    beat(p("I measured traffic effects in several ways. Ordinary-vehicle residence counts how long each desired trip remains in the system, including waiting before entry. Spatial exposure accumulates local increases in the number of vehicles occupying roads over time. Individual residence increases examine which travelers take longer. Following a common vehicle cohort lets the aggregate counts be checked against individual trip records.")+p("Selective control retained about 94% of aggressive control’s ambulance-time saving while reducing its traffic burden. Balanced mean ambulance duration was 401.57 seconds with routing alone, 211.19 seconds with aggressive joint control, and 222.29 seconds with selective joint control. Relative to aggressive control, selective priority added 11.10 seconds (95% interval: 9.47–12.94) while reducing accumulated excess road occupancy by 3.84 vehicle-hours (95% interval: 2.95–4.73). These paired comparisons quantify how much emergency speed is retained when the controller also accounts for surrounding traffic.")),
    [doc('ambugo-paper','Research paper'),link('https://github.com/mj-112358/AmbuGo-Final','Reproducible code & experiments'),link('my-projects.html#ambugo','System & deployment')]);

  const work=opening('Internships & work',[['human-archive','Human Archive'],['wink','Wink'],['handy','Academic website']])+
  story('human-archive','Human Archive','Business Growth & Machine Learning Data Intern · 18 May–29 June 2026',
    beat(p("At Human Archive, a YC-backed robotics-data startup, I developed 3D models of hand movement from recorded human actions. The work turns a demonstrated manipulation into a movement representation that robotics researchers can connect to a physical task and use in robot-learning datasets.")+p("The paired view shows the relationship directly: a person performs the task on the left, while the corresponding hand movement appears in three dimensions on the right. This connects the visible action to information about how the hand moves through it."),video('human-archive','Left: a person performs the task. Right: the corresponding hand movement represented in three dimensions.'))+
    beat(p("I worked on temporal synchronization and quality assurance across multimodal video, depth, motion, and tactile measurements. When a hand grasps or releases an object, those streams need to refer to the same moment. Video gives the task context, depth gives spatial geometry, movement describes the trajectory, and touch information records contact.")+p("I also trained and evaluated physical robots on everyday manipulation tasks, checking grasp success and task completion. Unsuccessful grasps and incomplete executions guided revisions to demonstrations and data-quality checks, linking data preparation to observed task performance. The hand models formed part of data products commercially supplied to six AI laboratories, connecting the custom movement representations to downstream robot-learning datasets."))+`<div class="robot-films">${video('human-archive-1','Physical robot trial: reaching toward and manipulating objects on the tabletop.')}${video('human-archive-2','A second manipulation trial, with a different object and grasp configuration.')}${video('human-archive-3','Robot manipulation trial with small tabletop objects.')}</div>`+
    beat(p("I managed partnerships with 12 manufacturing facilities and helped onboard more than 100 workers. This made authentic factory tasks available for collection and required coordinating facilities, participants, and recording operations alongside the technical representation work.")+p("I completed the six-week hybrid internship as the youngest intern in the company’s history, working across robotics data, physical trials, and industry collection operations.")),
    [doc('human-archive-letter','Internship completion letter'),link('videos/human-archive-1.mp4','Additional demonstration 1'),link('videos/human-archive-2.mp4','Additional demonstration 2'),link('videos/human-archive-3.mp4','Additional demonstration 3')])+
  story('wink','Wink','On-device retail behaviour analytics',
    beat(p("I built Wink to turn store-camera footage into measurements of how shoppers use a store. YOLO detects people in each frame; multi-object tracking connects their positions over time. Person re-identification uses appearance information to help relate observations of the same visitor, producing a movement history for a visit.")+p("I then connected that history to the store layout. A shopper’s tracked position is represented as a point, and a point-in-polygon test checks whether it falls inside a defined aisle, display area, or other zone. Timestamped zone-entry and exit events measure how long a shopper stays in an area, known as dwell time. Zone changes describe movement through the store."),photo('wink-zones','Frame from the Wink introduction video showing store zones and visitor tracking.'))+
    beat(p("The dashboard combines these events into visitor counts, stopping locations, time spent near displays, and movement summaries. Keeping a visitor’s identity consistent matters: repeated frames of someone standing still should add time to one visit. The reporting layer turns those accumulated observations into patterns a retailer can compare across areas and time periods."),photo('wink-dashboard','Dashboard frame from the Wink video, showing footfall and dwell-time summaries.'))+
    beat(p("I moved inference to the edge, running video analysis on retailers’ own computers and reducing the reported monthly operating cost from approximately $500 to $5 while keeping raw footage in the store. The retailer receives movement and dwell-time measurements from existing hardware. This connects the deployment architecture to two practical outcomes: lower recurring processing cost and local control of the video used to produce the analytics."),video('wink','Wink introduction: the camera-to-analytics workflow and the resulting product interface.')),
    [doc('resume','Technical & professional record'),link('videos/wink.mp4','Original project demonstration')])+
  story('handy','Professor Femida Handy’s academic website','Web developer · University of Pennsylvania, SP2',
    beat(p('I designed and implemented Professor Femida Handy’s academic website, organizing her research and professional work for visitors. The structure separates research areas, publications, books, and academic appointments so that a visitor can reach the relevant material without reading a résumé from beginning to end.')+p('I delivered the website within two weeks and incorporated each round of Professor Handy’s feedback.'),photo('handy-home','The live homepage of the academic website I developed for Professor Handy.')),
    [link('https://femidahandy.com/','Live website'),doc('resume','Résumé')]);

  const music=opening('Music')+
    `<section class="wrap music-first">${video('guitar','A short guitar performance. Sound can be enabled using the video controls.')}</section>`+
    story('guitar','Guitar','Ten years of practice and performance',
      beat(p('I’ve practised guitar for ten years and play electric and acoustic guitar in school ensembles, including performances with Indian instruments such as the sarangi. I performed as lead guitarist at my school’s annual day. Rehearsals involve working out the arrangement together: where the guitar supports the melody, when it should lead, and when to leave space for another instrument.')+p('My teacher, Kuldeepak Sir, once asked me to teach another student a song I had just learned. I carried that experience into Musica Universalis, where teaching guitar became part of my work in music education.'),photo('music-extra-2','Performing at a local concert.')),
      [doc('resume','Music activities in my résumé')])+
    `<section class="wrap photo-sequence"><h2>Performances & rehearsals</h2>${neatPhotos([['music-extra-0','My first-ever concert performance, aged 9.'],['music-extra-6','Performing on stage, aged 10.'],['school-annual-day-lead-guitar','Lead guitarist at my school’s annual day.'],['music-extra-3','Blending my electric guitar with traditional instruments like the sarangi.'],['music-extra-4','Performing at last year’s school annual day.'],['music-extra-5','A full-stage view of the ensemble.']],photo,'performance-grid')}</section>`+
    story('musica','Musica Universalis','President (2025) · Volunteer (2023–2024)',
      beat(p('I began by teaching guitar, then developed accessible digital lessons as technology head and later became president. Teaching made the practical barriers to learning visible: a child needs an instrument to practise on, an explanation they can return to, and someone who will listen when they try again. My work grew from individual lessons into helping coordinate those parts of the programme.')+p('Musica Universalis provides free lessons, instrument support, and performance opportunities. My contribution combines teaching, digital lesson development, and coordination with partner organizations. '))+
      beat(p('The teaching has a progression. Foundations of Sound offers weekly music-literacy classes for ages 6–18, introducing notation, rhythm, and fundamental musical skills through age-appropriate activities. Instrument donations and sponsorship help students practise between sessions.')+p('For learners who want a formal pathway, the programme provides technical coaching, theory, performance preparation, and graded assessment routes through Trinity College London and Bhatkhande classical music examinations. More than 600 students have enrolled in these pathways. Together, introductory lessons and exam preparation give students room to explore music and continue studying it in greater depth.'),neatPhotos([['musica-education','Working through a guitar demonstration together.'],['musica-exam-new','Students completing music-examination registration.'],['musica-exam-forms-new','Preparing Trinity and Bhatkhande examination forms.']],photo,'teaching-grid'))+
      beat(p('As president, I help connect teaching with a wider volunteer and partner network. The current programme reports a team of more than 25 and partnerships with seven NGOs and a music conservatoire, including Impact, Naya Savera, Aashray, and Soul of Symphony. Partners provide local settings in which lessons, instruments, and events can reach learners.')+p('World Without Walls extends that work across on-site teams in India, China, Ukraine, and London. Students share musical traditions and collaborate on compositions, while an international newsletter connects the chapters and carries their work to a wider audience. The programme reports reaching more than 5,000 people through education, live events, and the newsletter.'),photo('musica-group-new','A Musica Universalis community session.'))+
      beat(p('The programme also includes SoulCare, music-therapy sessions supported by licensed therapists for children experiencing anxiety or trauma. Alongside teaching and performances, this gives music a place in emotional support. '))+
      beat(p('Performance gives that learning a public setting. At Aashray Fest, Musica Universalis worked with Aashray Care Home on an event supported by the Government of Rajasthan and attended by eight Rajasthan government officials. ')+p('This is the connection I want to maintain as the programme grows: a first lesson should lead to opportunities to practise, learn with others, and eventually perform. Organizing partnerships and digital lessons helps those opportunities continue between individual sessions.'),neatPhotos([['musica-aashray-stage','Performers on stage at Aashray Fest 2026, held with Aashray Care Home. Performance opportunities are part of Musica’s education programme.'],['musica-aashray-presentation','Sharing Musica Universalis at Aashray Fest 2026.']],photo,'aashray-gallery')),
      [link('https://musicauni.netlify.app/','Programmes, partnerships & Aashray Fest'),link('https://musicauni.netlify.app/team','Team & presidency'),link('https://www.soulofsymphony.in/','Soul of Symphony'),doc('resume','Personal role & activity record')]);

  const community=opening('Community',[['viking-clap','School community'],['learning','Students For Last-Mile Learning'],['school','Student leadership'],['care','Kids Cancer Foundation']])+
  story('viking-clap','The Viking clap','School community',beat(p('The Viking clap is a school tradition at sports matches: the crowd claps in time with the drumbeat to build energy and cheer on our players. I played the drums, setting the rhythm for the school community.'),`<div class="viking-pair">${video('viking-clap','Viking clap with the school community. Enable sound using the video controls.')}${photo('viking-drums','Playing the drums for the Viking clap.')}</div>`))+
  story('learning','Students For Last-Mile Learning','Finance & Technology Head',
    beat(p('Students For Last-Mile Learning brings together funding, rural schools, and student-led organizations. I led fundraising that secured $185,000 through a CSR partnership for Ekal Abhiyan, supporting one year of education for 16,500 children across 550 schools. My work connected the student initiative with an established educational network that could put the funding to use.')+p('Ekal’s one-teacher school model provides basic education in rural and tribal villages. SFLML reports work across 20 states. Its endorsement letters record ₹1.65 crore raised, including ₹55 lakh in confirmed direct transfers, with funds allocated to the Friends of Tribal Society’s Jaipur chapter. Funding a full school year gave our fundraising a concrete purpose: sustained educational support delivered through schools already working within those communities.'),photo('sflml-0','Working with children during an SFLML activity. Hands-on sessions complement the initiative’s funding and school partnerships.'))+
    beat(p('Funding is one part of the initiative. SFLML also brings student organizations together to provide workshops, learning materials, and guidance. Its partner network covers music, theatre, STEM, digital skills, careers, health, design, and financial literacy. The initiative mobilized 2,400 students and conducted more than 30 student-led workshops, alongside donation drives. This lets different student groups contribute what they know to a shared educational effort.')+p('Musica Universalis contributes music learning; KahaaniGhar uses theatre and storytelling; STEM Simplified and StemCast develop science activities and learning resources; Unnati provides career and scholarship guidance; and Tech4Bharat teaches smartphone and internet skills. Our website connects this work with the wider network so that a school can receive support from more than one student initiative.')+`<details class="model-results"><summary>Explore the full student-partner network</summary><p>The network also includes Headstart, Toyforever, DhanSarthi, ResistRx, ElevatED, Suraksha, The Dezign Cue, Jivam Foundation, Izhar Foundation, Write to Rise, Kartavya, Uniquest, FRC Kaizen #10428, and DhanRaksha, alongside individual contributors. Their work ranges from books and stationery drives to entrepreneurship, menstrual-health education, girls’ mentoring, robotics outreach, and financial inclusion.</p>${link('https://www.sflml.com/#work','Partner descriptions & workshops')}</details>`,photo('sflml-2','A school associated with SFLML’s last-mile education work.'))+
    beat(p('The August 12–13, 2025 flagship event gave that network a place to meet. Rooted in Culture brought traditional performances, art, and craft into the programme. Join the Mission & Our Work presented the initiative’s partnerships and invited more students to contribute.')+p('SolvED added a practical design challenge: students developed and pitched responses to educational and infrastructural problems facing rural children, including health, technology access, and gender equity. The event connected cultural participation with a route into student-led problem solving.'),photo('sflml-1','The SFLML team at Rooted in Culture. The 2025 event connected cultural activities, partner outreach, and the SolvED challenge.'))+
    beat(p('The initiative received a world record for the largest fundraiser for tribal education by high school students. ')+p(' As Finance & Technology Head, I worked on the funding and technology that helped connect those efforts.'),photo('sflml-3','World-record recognition for SFLML’s student-led tribal-education fundraiser.')),
    [link('https://www.sflml.com/','Initiative, events & impact'),link('https://www.sflml.com/#work','Ekal partnership & student network'),link('images/sflml-kothari-letter.png','Justice S. S. Kothari’s letter'),link('images/sflml-ranka-letter.png','Justice Jainendra Kumar Ranka’s letter'),doc('resume','Personal role & fundraising record')])+
  story('school','Student Council & research mentoring','Deputy Head Boy · Jayshree Periwal International School',
    beat(p('As Deputy Head Boy in a school community of more than 2,550 students, I organized a 15-school competition and held five workshops on the digital divide and algorithmic bias. ')+p('After ISEF, I also mentored younger researchers. I helped 40 projects refine research questions, troubleshoot experiments, and examine the relationship between a claim and its evidence. Seventeen advanced to the IRIS National Fair.'),photo('school-leadership','Speaking at school as Deputy Head Boy.'))+
    beat(p('That mentoring work draws directly on the research process. A project needs a question that can be tested, a comparison that makes the result interpretable, and measurements that support the conclusion. Helping students make those connections became a way to share what I had learned from my own experiments.')),
    [doc('resume','Leadership & mentoring record')])+
  story('care','Kids Cancer Foundation','India Chapter Director',
    beat(p('At Kids Cancer Foundation, an initiative founded alongside ISEF finalists, I helped advance two project directions: low-cost cancer therapeutics and donor–patient matching software intended to expand treatment access. These bring different constraints into focus, from the cost of treatment to the process of connecting a patient with a potential donor.')+p('We also donated toys to hospitalized children. The initiative combines longer-term research and software work with direct support during hospital stays.')),
    [link('https://kidscancerfoundation.org/','Kids Cancer Foundation'),doc('resume','Activity record')]);

  const spirometry=opening('Physics-informed spirometry')+research.slice(research.indexOf('<article class="case-study wrap" id="spirometry">'),research.indexOf('<article class="case-study wrap" id="ambugo-study">'));
  return {projects,research,spirometry,work,music,community};
}
